import{_ as a,o as r,c as e,a6 as i}from"./chunks/framework.BoFLe3f3.js";const p=JSON.parse('{"title":"团队工作坊：半天把精通模型跑一遍","description":"面向 4–8 人团队的四小时工作坊脚本：诊断接力、架构辩论与 PR 评审，产出可复用的回归断言与 ADR。","frontmatter":{"title":"团队工作坊：半天把精通模型跑一遍","description":"面向 4–8 人团队的四小时工作坊脚本：诊断接力、架构辩论与 PR 评审，产出可复用的回归断言与 ADR。"},"headers":[],"relativePath":"workshop.md","filePath":"workshop.md","lastUpdated":1793422332000}'),l={name:"workshop.md"};function o(d,t,s,n,h,c){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="团队工作坊" tabindex="-1">团队工作坊 <a class="header-anchor" href="#团队工作坊" aria-label="Permalink to &quot;团队工作坊&quot;">​</a></h1><p>个人练习解决「知道」，团队工作坊解决「对齐」。目标不是讲完一章，而是让团队在同一套判据下讨论问题。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>刚升级到 Next.js 16.4，需要统一缓存、鉴权与即时导航的心智模型；</li><li>团队评审经常争论「该不该缓存」「要不要 use client」；</li><li>线上事故复盘后，希望把经验固化成门禁。</li></ul><h2 id="四小时议程" tabindex="-1">四小时议程 <a class="header-anchor" href="#四小时议程" aria-label="Permalink to &quot;四小时议程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时段</th><th>环节</th><th>产出</th></tr></thead><tbody><tr><td>0:00–0:20</td><td>用<a href="/nextjs-tutorial-site/version-matrix">版本能力矩阵</a>对齐变化点</td><td>团队认可的迁移检查清单</td></tr><tr><td>0:20–1:20</td><td>诊断接力：每组抽 1 个<a href="/nextjs-tutorial-site/mastery">诊断剧本</a></td><td>假设树 + 回归断言</td></tr><tr><td>1:20–2:10</td><td>架构辩论：抽 1 张决策卡，正反方各选一个方案</td><td>一份 ADR 草稿</td></tr><tr><td>2:10–2:25</td><td>休息</td><td>—</td></tr><tr><td>2:25–3:15</td><td>PR 评审对抗：同一段 diff，各自写发现</td><td>发现清单 + 评分对照</td></tr><tr><td>3:15–3:50</td><td>落地：把一条断言接进 CI</td><td>一条可运行的门禁</td></tr><tr><td>3:50–4:00</td><td>复盘：哪些判据仍模糊</td><td>下次工作坊主题</td></tr></tbody></table><h2 id="角色分工" tabindex="-1">角色分工 <a class="header-anchor" href="#角色分工" aria-label="Permalink to &quot;角色分工&quot;">​</a></h2><ul><li><strong>主持人</strong>：控时，保证每轮先写后说，避免被声音大的人带偏。</li><li><strong>记录员</strong>：把假设、被排除的分支、决策与否决理由写进共享文档。</li><li><strong>质疑者</strong>：每轮至少提出一个「如果反过来呢」的问题。</li><li><strong>落地人</strong>：负责把至少一条回归断言变成 CI 步骤。</li></ul><h2 id="三个练习的具体做法" tabindex="-1">三个练习的具体做法 <a class="header-anchor" href="#三个练习的具体做法" aria-label="Permalink to &quot;三个练习的具体做法&quot;">​</a></h2><h3 id="_1-诊断接力" tabindex="-1">1. 诊断接力 <a class="header-anchor" href="#_1-诊断接力" aria-label="Permalink to &quot;1. 诊断接力&quot;">​</a></h3><ol><li>只把 symptom 与 evidence 投屏，所有人独立写 5 分钟假设树；</li><li>每人说一个假设与验证方式，不允许直接说答案；</li><li>主持人逐条标记「根因 / 次因 / 排除」，并追问排除理由；</li><li>对照剧本的修复与回归，挑一条写成本团队的断言。</li></ol><p><strong>判据</strong>：好的假设树能解释全部观测现象；只解释一半的假设要标为「未收敛」。</p><h3 id="_2-架构辩论" tabindex="-1">2. 架构辩论 <a class="header-anchor" href="#_2-架构辩论" aria-label="Permalink to &quot;2. 架构辩论&quot;">​</a></h3><ol><li>读 context 与 constraints，正反方各认领一个选项；</li><li>每方用「延迟、成本、一致性、可维护性」四个维度陈述代价；</li><li>主持人只允许用约束反驳，不允许用「我觉得」；</li><li>合并成一份 ADR：决策、后果、失效条件、评审问题。</li></ol><p><strong>判据</strong>：如果 ADR 里没有「什么条件下推翻它」，说明还没想清楚。</p><h3 id="_3-pr-评审对抗" tabindex="-1">3. PR 评审对抗 <a class="header-anchor" href="#_3-pr-评审对抗" aria-label="Permalink to &quot;3. PR 评审对抗&quot;">​</a></h3><ol><li>同一段 diff，每人 10 分钟写发现，按严重度排序；</li><li>先对齐「哪些是 P0」，再对齐数量；</li><li>对照参考发现，讨论漏掉的原因：是知识缺口，还是流程缺口；</li><li>把高频漏项写进团队评审清单。</li></ol><p><strong>判据</strong>：连续两轮都漏掉同一类问题，说明需要在 CI 里加检查，而不是继续靠人眼。</p><h2 id="会后落地清单" tabindex="-1">会后落地清单 <a class="header-anchor" href="#会后落地清单" aria-label="Permalink to &quot;会后落地清单&quot;">​</a></h2><ul><li>[ ] 每条回归断言都有负责人和截止日期</li><li>[ ] ADR 进入仓库 <code>docs/adr/</code>，并在相关代码旁引用</li><li>[ ] 评审清单更新到 PR 模板</li><li>[ ] 下一次工作坊主题与日期确定</li></ul><p>配套材料：<a href="/nextjs-tutorial-site/mastery">精通中心</a> · <a href="/nextjs-tutorial-site/troubleshooting">排障图谱</a> · <a href="/nextjs-tutorial-site/performance">性能预算</a> · <a href="/nextjs-tutorial-site/contributing">贡献者模板</a>。</p>',21)])])}const f=a(l,[["render",o]]);export{p as __pageData,f as default};
